import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

const AdminCheckins = () => {
    const [users, setUsers] = useState([]);
    const [selectedUser, setSelectedUser] = useState(null);
    const [checkins, setCheckins] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        fetchUsers();
    }, []);

    // Obtener todos los usuarios
    const fetchUsers = async () => {
        try {
            const response = await fetch('https://requena-backend-production.up.railway.app/admin/users');
            if (!response.ok) throw new Error('Error al cargar usuarios');
            const data = await response.json();
            setUsers(data);
        } catch (error) {
            console.error('Error al cargar usuarios:', error);
        }
    };

    // Obtener el historial de check-ins de un usuario
    const fetchCheckins = async (userId) => {
        try {
            const response = await fetch(`https://requena-backend-production.up.railway.app/admin/user-checkins/${userId}`);
            if (!response.ok) throw new Error('Error al obtener historial de check-ins');
            const data = await response.json();
            setCheckins(data);
            setSelectedUser(userId);
        } catch (error) {
            console.error('Error al obtener historial de check-ins:', error);
        }
    };

    return (
        <div className="p-6 bg-gray-100 min-h-screen">
            <button className="mb-4 bg-gray-700 text-white px-4 py-2 rounded" onClick={() => navigate('/admin')}>
                Volver al Panel
            </button>
            <h1 className="text-3xl font-bold mb-6">Gestión de Check-ins y Check-outs</h1>
            <div className="bg-white shadow-lg rounded-lg p-4">
                <h2 className="text-xl font-semibold mb-4">Lista de Usuarios</h2>
                <table className="w-full">
                    <thead>
                    <tr className="bg-gray-200">
                        <th className="p-3">Nombre</th>
                        <th className="p-3">Correo</th>
                        <th className="p-3">Acciones</th>
                    </tr>
                    </thead>
                    <tbody>
                    {users.map((user) => (
                        <tr key={user.id} className="border-b">
                            <td className="p-3">{user.name}</td>
                            <td className="p-3">{user.email}</td>
                            <td className="p-3">
                                <button
                                    onClick={() => fetchCheckins(user.id)}
                                    className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600"
                                >
                                    Ver Historial
                                </button>
                            </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            </div>
            {selectedUser && (
                <div className="mt-6 bg-white shadow-lg rounded-lg p-4">
                    <h2 className="text-xl font-semibold mb-4">Historial de Check-ins y Check-outs</h2>
                    {checkins.length === 0 ? (
                        <p>No hay registros de check-in/check-out para este usuario.</p>
                    ) : (
                        <>
                            <table className="w-full">
                                <thead>
                                <tr className="bg-gray-200">
                                    <th className="p-3">Fecha y Hora</th>
                                    <th className="p-3">Tipo</th>
                                    <th className="p-3">Ubicación</th>
                                </tr>
                                </thead>
                                <tbody>
                                {checkins.map((c) => (
                                    <tr key={c.timestamp} className="border-b">
                                        <td className="p-3">{new Date(c.timestamp).toLocaleString()}</td>
                                        <td className="p-3">{c.type}</td>
                                        <td className="p-3">{c.latitude}, {c.longitude}</td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                            <div className="mt-6">
                                <h3 className="text-lg font-semibold mb-2">Mapa de Check-ins</h3>
                                <MapContainer center={[19.4326, -99.1332]} zoom={12} className="h-96 w-full">
                                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                    {checkins.map((c, index) => (
                                        <Marker key={index} position={[c.latitude, c.longitude]}>
                                            <Popup>
                                                {c.type.toUpperCase()} - {new Date(c.timestamp).toLocaleString()}
                                            </Popup>
                                        </Marker>
                                    ))}
                                </MapContainer>
                            </div>
                        </>
                    )}
                </div>
            )}
        </div>
    );
};

export default AdminCheckins;
